// Everything an `ErrorSummary` does once a script is running.
//
// IT SHIPS, for `ColorPicker`'s reason: a component whose consumer cannot use
// it is a component that lies.
//
// FOUR THINGS, AND NOT ONE OF THEM IS THE LIST WHERE A SERVER SENT ONE:
//
// 1. It takes the focus. After a refusal the reader is at the bottom of the
//    form, on the control they pressed, and what went wrong is above them.
//    Moving focus here is the only thing that puts the two in one place.
// 2. It sends focus to the CONTROL when an entry is followed. A fragment
//    pointing at a `<fieldset>` scrolls to the group and leaves focus behind
//    it, and a fragment pointing at a control the script has hidden — a
//    `Select`'s native element — reaches something a reader cannot see.
// 3. With `collect` it catches the browser's own refusal, puts the browser's
//    own sentence where this system already says sentences, and reads the list
//    back out of the fields. NOT ONE WORD OF LANGUAGE IS INVENTED HERE:
//    `validationMessage` is the platform's, in the platform's language, and a
//    sentence the caller already wrote is never overwritten. `Select` reached
//    this arrangement first (`shell.js`), for a control whose real element it
//    had hidden; this is the same repair for a whole form.
// 4. It puts a word in front of the document's title while it has something to
//    say, and takes it off again — which is how somebody switching between
//    tabs finds the one that wants them back.
//
// WHAT IT NEVER DOES: announce anything itself. The `role="alert"` the
// component renders is the announcement, and a second live region saying the
// same thing is the same sentence twice.

import { fill, saySentence, sentenceOf } from "./messages.js";

/** The controls a fragment may legitimately land on. */
const FOCUSABLE =
  "input:not([type=hidden]):not([hidden]), select:not([hidden]), textarea, button, [tabindex]:not([tabindex='-1'])";

/**
 * The thing a reader should end up on, from whatever the entry points at.
 *
 * A `<fieldset>` is a group and not a control; a hidden native `<select>` is a
 * control nobody can see. Both are legitimate targets for a *link* — the id is
 * where the field is — and neither is where focus belongs.
 */
function target(id) {
  const found = document.getElementById(id);
  if (!found) return null;
  const seen = (one) => one.offsetParent !== null || one === document.body;
  if (found.matches(FOCUSABLE) && seen(found)) return found;
  // Inside it first — a `<fieldset>` is a group, and the box a reader has to
  // change is one of the ones in it.
  const within = [...found.querySelectorAll(FOCUSABLE)].find(seen);
  if (within) return within;
  // Then out to the field it belongs to, which is how a control the script has
  // hidden — a `Select`'s real `<select>` — hands over to the one a reader can
  // actually see. Never further than the field: the next control along is a
  // different question, and answering it is not what they asked for.
  const field = found.closest(".nd-field, .nd-fieldset");
  return [...(field?.querySelectorAll(FOCUSABLE) ?? [])].find(seen) ?? found;
}

/** The error paragraph belonging to a control, by the one id rule `Field` states. */
function slotFor(control) {
  const field = control.closest(".nd-field, .nd-fieldset");
  return field?.querySelector("[data-nd-field-error]") ?? null;
}

export function enhanceErrorSummaries(root = document) {
  for (const element of root.querySelectorAll("[data-nd-error-summary]")) {
    if (element.dataset.ndEnhanced) continue;
    element.dataset.ndEnhanced = "error-summary";
    enhance(element);
  }
}

function enhance(root) {
  const list = root.querySelector("[data-nd-error-summary-list]");
  const template = root.querySelector("[data-nd-error-summary-template]");
  const collect = root.getAttribute("data-nd-collect") === "true";
  const wanted = root.getAttribute("data-nd-form");
  const form = wanted ? document.getElementById(wanted) : root.closest("form");
  const prefix = root.getAttribute("data-nd-title-prefix");
  const takesFocus = root.getAttribute("data-nd-focus") !== "false";
  const original = document.title;
  let empty = null;

  // FOCUS GOES TO THE CONTROL, NOT TO WHATEVER THE FRAGMENT REACHED.
  root.addEventListener("click", (event) => {
    const link = event.target.closest?.("[data-nd-error-summary-link]");
    const id = link?.getAttribute("href")?.slice(1);
    if (!id) return;
    const control = target(id);
    if (!control) return;
    event.preventDefault();
    // The browser's own scrolling, and the reader's own motion setting with
    // it — `scrollIntoView` honours `prefers-reduced-motion` and a hand-rolled
    // animation does not.
    control.scrollIntoView({ block: "center", behavior: "auto" });
    control.focus({ preventScroll: true });
  });

  /**
   * Whether it has anything to say, and the document's title with it.
   *
   * The title is put in front once and taken off once, from the title the page
   * had when this ran — a title that gains a word per refusal is a tab strip
   * nobody can read.
   */
  function settle() {
    const nothing = (list?.childElementCount ?? 0) === 0;
    if (nothing === empty) return nothing;
    empty = nothing;
    root.toggleAttribute("data-nd-empty", nothing);
    if (prefix) {
      document.title = nothing
        ? original
        : prefix.includes("{title}")
          ? fill(prefix, { title: original })
          : `${prefix} ${original}`;
    }
    return nothing;
  }

  /** Reads what is wrong from the form itself, in the order a reader walks it. */
  function build() {
    if (!collect || !list || !template || !form) return;
    list.replaceChildren();
    for (const slot of form.querySelectorAll("[data-nd-field-error]")) {
      const sentence = sentenceOf(slot);
      if (!sentence) continue;
      // The id the field derived its own error id from — one rule, stated in
      // `Field.control`'s documentation, read back here rather than guessed.
      const control = slot.id.replace(/-error$/, "");
      const row = template.content.firstElementChild.cloneNode(true);
      const link = row.querySelector("[data-nd-error-summary-link]");
      link.setAttribute("href", `#${control}`);
      link.textContent = sentence;
      list.append(row);
    }
  }

  function arrive() {
    if (settle()) return;
    if (!takesFocus) return;
    root.focus({ preventScroll: false });
  }

  if (collect && form) {
    /** Takes back only what this file wrote, never a sentence a caller wrote. */
    function clear(control) {
      const slot = slotFor(control);
      if (slot?.dataset.ndSaid === undefined) return;
      delete slot.dataset.ndSaid;
      saySentence(slot, "");
      slot.closest(".nd-field, .nd-fieldset")?.setAttribute("data-nd-invalid", "false");
      control.setAttribute("aria-invalid", "false");
    }

    // AFTER THE BROWSER HAS REFUSED, not instead of it. `submit` never fires
    // on an invalid form, and `invalid` does not bubble — so it is caught on
    // the way down, once per refused control, and the list is built on the
    // next task when every refusal has landed.
    let pending = null;
    form.addEventListener(
      "invalid",
      (event) => {
        const control = event.target;
        const slot = slotFor(control);
        // No slot is a field this cannot speak for: the browser's own bubble
        // is then the only thing the reader has, and taking it away would
        // leave them nothing.
        if (!slot) return;
        // The bubble is refused because the same sentence is about to be said
        // in the two places a reader will actually look — beside the answer,
        // and at the top of the form.
        event.preventDefault();
        if (!sentenceOf(slot)) {
          saySentence(slot, control.validationMessage);
          slot.dataset.ndSaid = "";
        }
        slot.closest(".nd-field, .nd-fieldset")?.setAttribute("data-nd-invalid", "true");
        control.setAttribute("aria-invalid", "true");
        clearTimeout(pending);
        pending = setTimeout(() => {
          build();
          arrive();
        }, 0);
      },
      true,
    );

    // Whatever was said stops being true the moment the answer does.
    for (const event of ["input", "change"]) {
      form.addEventListener(
        event,
        (moment) => {
          const control = moment.target;
          if (typeof control.checkValidity !== "function") return;
          if (!control.checkValidity()) return;
          clear(control);
          build();
          settle();
        },
        true,
      );
    }

    // And a form that submits cleanly leaves nothing behind.
    form.addEventListener("submit", () => {
      list?.replaceChildren();
      settle();
    });

    build();
    settle();
    // A server that rendered sentences into the fields has already said what
    // is wrong, and this is then the same arrival as any other.
    if (!empty && takesFocus) root.focus({ preventScroll: false });
  } else {
    arrive();
  }
}
